package run.ikaros.finance; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/finance/ledgers/{ledgerId}/transaction-templates") public class TransactionTemplateController{private final TransactionTemplateService service;public TransactionTemplateController(TransactionTemplateService s){service=s;}@PostMapping public Mono<TransactionTemplateView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@Valid@RequestBody CreateTransactionTemplateRequest r){return service.create(a,ledgerId,r);}@GetMapping public Flux<TransactionTemplateView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId){return service.list(a,ledgerId);}@PostMapping("/{id}/actions/archive")public Mono<TransactionTemplateView> archive(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.archive(a,id);}}
